      .filter((dependency) => earliest[dependency].finish === start)
      .map((dependency) => criticalPathById.get(dependency)!)
      .sort(comparePaths);
    const path = candidateDependencies.length === 0
      ? [id]
      : [...candidateDependencies[0], id];

